  # @param search_ended_at character The timestamp when the search operation ended. (optional)
  # @param search_notes character Notes and field remarks recorded during the station search. (optional)
  # @param search_result_type_name character Description name of the search result type. (optional)
  # @param search_started_at character The timestamp when the search operation started. (optional)
  # @param survey_year character Calendar year in integer format YYYY during which data was collected. (optional)
  # @param target_station_code character Code of the target sampling site station. (optional)
  # @param untrawlable_site_reason_name character Description of the untrawlable reason. (optional)
