test_that("GetNwfscSurveyTaxonomy", {
  # tests for GetNwfscSurveyTaxonomy
  # base path: https://www.webapps.nwfsc.noaa.gov/data-catalog/api/v1
  # NWFSC Survey Taxonomy
  # The full taxonomic hierarchy dataset used by at-sea data collection processes and shoreside reporting at NWFSC. The backbone of this report is its tie in to both WoRMS (https://www.marinespecies.org/) and ITIS (https://www.itis.gov/) linkages via worms_aphia_id and itis_tsn values.
  # @param limit integer Max rows to return (optional)
  # @param fields array[character] Comma-separated column filter (optional)
  # @param offset integer Rows to skip before beginning to return records. (optional)
  # @param redirect character Force S3 pre-signed redirect (optional)
  # @param data_format character Response format: json, csv, or parquet (optional)
  # @param response_mode character Delivery mode: data, package (optional)
  # @param include_noncore_fields character All fields returned when true, else only core fields returned. (optional)
  # @param bottom_trawl_taxon_alias character Bottom Trawl preferred alias (optional)
  # @param hierarchy_level_name character Taxonomic rank (e.g. Species, Genus) (optional)
  # @param hook_and_line_taxon_alias character Hook & Line preferred alias (optional)
  # @param is_bird character Flag indicating if taxon is a bird (optional)
  # @param is_bony_fish character Flag indicating if taxon is a bony fish (optional)
  # @param is_coral character Flag indicating if taxon is a coral (optional)
  # @param is_herring character Flag indicating if taxon is a herring (optional)
  # @param is_invertebrate character Flag indicating if taxon is an invertebrate (optional)
  # @param is_jawless_fish character Flag indicating if taxon is a jawless fish (optional)
